import React, { useState } from 'react';
import Navbar from './components/Navbar';
import Sidebar from './components/Sidebar';
import Home from './components/Home';
import Timetable from './components/Timetable';
import Teachers from './components/Teachers';
import About from './components/About';
import LmsDashboard from './components/LmsDashboard';
import Footer from './components/Footer';

export default function App() {
  const [currentPage, setCurrentPage] = useState('Dashboard');
  const [showLoginModal, setShowLoginModal] = useState(false);
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [studentName, setStudentName] = useState('');
  const [inputName, setInputName] = useState('');
  const [inputPassword, setInputPassword] = useState('');

  const handleLoginSubmit = async (e) => {
    e.preventDefault();
    setShowLoginModal(false);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', minHeight: '100vh', backgroundColor: '#f4f6f9', fontFamily: 'sans-serif' }}>
      <Navbar 
        onLoginClick={() => setShowLoginModal(true)}
        isLoggedIn={isLoggedIn}
        studentName={studentName}
        setCurrentPage={setCurrentPage}
        currentPage={currentPage}
      />

      <div style={{ display: 'flex', flex: 1 }}>
        <Sidebar setCurrentPage={setCurrentPage} currentPage={currentPage} /> 

        <div style={{ flex: 1, padding: '25px', display: 'flex', flexDirection: 'column', justifyContent: 'space-between' }}>
          <div>
            {currentPage === 'Dashboard' && <LmsDashboard />}
            {currentPage === 'Overview' && <LmsDashboard />}
            {currentPage === 'Classes' && <Timetable setCurrentPage={setCurrentPage} />}
            {currentPage === 'Teachers & Classes' && <Teachers />}
            {currentPage === 'Students' && <div style={{ background: '#fff', padding: '20px', borderRadius: '10px' }}><h2>Student Management System</h2><p>Student details and management area.</p></div>}
          </div>
          <Footer />
        </div>
      </div>
    </div>
  );
}
